Body:
The `resolveRuntimeHeaders` function doesn't validate or sanitize the values being substituted into headers. If `session.title` contains newline characters (`\n`, `\r`) or other HTTP header-breaking characters, this could lead to HTTP header injection vulnerabilities or malformed requests.

Consider sanitizing the values before substitution:
```typescript
function sanitizeHeaderValue(value: string): string {
  return value.replace(/[\r\n]/g, ' ').trim()
}

function resolveRuntimeHeaders(
  headers: Record<string, string> | undefined,
  ctx: RuntimeContext,
): Record<string, string> {
  if (!headers) return {}
  const result: Record<string, string> = {}
  for (const [key, value] of Object.entries(headers)) {
    result[key] = sanitizeHeaderValue(
      value
        .replace(/\{session:id\}/g, ctx.sessionUUID)
        .replace(/\{session:title\}/g, ctx.sessionTitle)
        .replace(/\{project:id\}/g, ctx.projectID)
        .replace(/\{request:id\}/g, ctx.requestID)
    )
  }
  return result
}
```

The new runtime header resolution functionality (`sessionToUUID`, `resolveRuntimeHeaders`, and runtime context) lacks test coverage. Given that this repository has existing test infrastructure (e.g., `packages/opencode/test/session/session.test.ts`), consider adding tests to verify:

1. UUID generation consistency for the same session ID
2. Correct template variable replacement in headers
3. Handling of edge cases (undefined headers, empty strings, special characters in titles)
4. Security validation (header injection prevention)

Example test structure:
```typescript
describe("runtime header resolution", () => {
  test("should consistently generate UUID from session ID", () => {
    const uuid1 = sessionToUUID("session_123")
    const uuid2 = sessionToUUID("session_123")
    expect(uuid1).toBe(uuid2)
  })

  test("should replace template variables in headers", () => {
    const headers = {
      "X-Session-Id": "{session:id}",
      "X-Session-Title": "{session:title}",
    }
    const ctx = {
      sessionUUID: "123e4567-e89b-12d3-a456-426614174000",
      sessionTitle: "Test Session",
      projectID: "proj_123",
      requestID: "req_456"
    }
    const result = resolveRuntimeHeaders(headers, ctx)
    expect(result["X-Session-Id"]).toBe("123e4567-e89b-12d3-a456-426614174000")
    expect(result["X-Session-Title"]).toBe("Test Session")
  })
})
```

